import mri from "mri";
function camelCase(option) {
	return option.replace(/-([a-z])/g, (_, letter) => letter.toUpperCase());
}
function normalizeNegativePortArguments(args) {
	const normalized = [];
	for (let index = 0; index < args.length; index++) {
		if (args[index] === "--") {
			normalized.push(...args.slice(index));
			break;
		}
		if (args[index] === "--port" && /^-\d/.test(args[index + 1] ?? "")) {
			normalized.push(`--port=${args[++index]}`);
		} else {
			normalized.push(args[index]);
		}
	}
	return normalized;
}
export class MriCliArgumentParser {
	parse(args) {
		const parsed = mri(normalizeNegativePortArguments(args), {
			boolean: ["global"],
			alias: { g: "global" }
		});
		const flags = { _: parsed._ };
		for (const [option, value] of Object.entries(parsed)) {
			if (option !== "_") flags[camelCase(option)] = value;
		}
		return flags;
	}
}
